INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31511, 'Philemon 1:5', 'Philemon', 1, 5, 'ځکه چې زه ستا د مینې نه چې د خدای د ټولو خلکو سره یې لرې او په څښتن عیسی باندې د ایمان نه خبر یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_5.mp3', '', 1761754199, 1761754199),
(31512, 'Philemon 1:6', 'Philemon', 1, 6, 'زما دعا دا ده چې ته خپل د ایمان شراکت داسې ښکاره کړې چې د دې سبب شي، ترڅو زمونږ پوهه د هغو برکتونو په اړه چې په مسیح کې یې لرو، زیاته شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_6.mp3', '', 1761754199, 1761754199),
(31513, 'Philemon 1:7', 'Philemon', 1, 7, 'ای زما وروره، ماته ستا د مینې له امله ډېره خوشحالي او تسلي پیدا شوې ده، ځکه چې ستا له امله د خدای د خلکو زړونه قوي او تازه شوي دي. د فیلیمون نه د اونیسیموس په خاطر د پولوس غوښتنه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_7.mp3', '', 1761754199, 1761754199),
(31514, 'Philemon 1:8', 'Philemon', 1, 8, 'سره له دې چې زه په مسیح کې دا زړورتیا او جرات لرم چې تاته حکم وکړم چې هغه کار وکړه چې مناسب وي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_8.mp3', '', 1761754199, 1761754199),
(31515, 'Philemon 1:9', 'Philemon', 1, 9, 'خو زه د هغې مینې له امله چې تا سره یې لرم او زه پولوس د یو سپین‌ږیري سړي په توګه چې اوس د عیسی مسیح په خاطر زنداني یم، ستا نه د یو څه غوښتنه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_9.mp3', '', 1761754199, 1761754199),
(31516, 'Philemon 1:10', 'Philemon', 1, 10, 'زه د خپل زوی اونیسیموس له خوا چې د خپل بندیتوب په وخت کې د هغه روحاني پلار شوم، ستا نه غوښتنه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_10.mp3', '', 1761754199, 1761754199),
(31517, 'Philemon 1:11', 'Philemon', 1, 11, 'هغه یو وخت ستا دپاره ګټور نه ؤ، خو اوس هم ستا او هم زما دپاره ګټور دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_11.mp3', '', 1761754199, 1761754199),
(31518, 'Philemon 1:12', 'Philemon', 1, 12, 'زه هغه تاته بېرته درلېږم چې زما د زړه سر دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_12.mp3', '', 1761754199, 1761754199),
(31519, 'Philemon 1:13', 'Philemon', 1, 13, 'ما غوښتل چې هغه د خپل ځان سره وساتم، ترڅو تر هغه وخته پورې چې زه د زېري په خاطر په زندان کې یم، هغه ستا په ځای زما خدمت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_13.mp3', '', 1761754199, 1761754199),
(31520, 'Philemon 1:14', 'Philemon', 1, 14, 'خو ما ونه غوښتل چې ستا له غوښتنې نه پرته کوم کار وکړم، ترڅو ستا نېکي د مجبوریت له مخې نه بلکې ستا په رضا سره وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_14.mp3', '', 1761754199, 1761754199),
(31521, 'Philemon 1:15', 'Philemon', 1, 15, 'کېدای شي هغه د دې دپاره ستا نه د لږ وخت دپاره بېل شو چې هغه د تل دپاره ستا سره وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_15.mp3', '', 1761754199, 1761754199),
(31522, 'Philemon 1:16', 'Philemon', 1, 16, 'خو هغه اوس نور د یو غلام په شان نه، بلکې د غلام نه ډېر لوړ دی، لکه د یو ګران ورور په شان. هغه چې دومره ماته ګران دی، نو څومره به تاته هم د غلام او هم په څښتن کې د یو ورور په توګه ګران وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_16.mp3', '', 1761754199, 1761754199),
(31523, 'Philemon 1:17', 'Philemon', 1, 17, 'نو که چېرې ته ما خپل شریک ګڼې، لکه څنګه چې ما منې، هغه هم ومنه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_17.mp3', '', 1761754199, 1761754199),
(31524, 'Philemon 1:18', 'Philemon', 1, 18, 'که چېرې هغه ستا سره کومه بدي کړې وي او یا ستا ورباندې کوم پور وي، نو هغه زما په حساب ولیکه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_18.mp3', '', 1761754199, 1761754199),
(31525, 'Philemon 1:19', 'Philemon', 1, 19, 'زه پولوس دا درته په خپل لاس لیکم چې زه به دا هرڅه بېرته درکړم. زه دا نه وایم چې ته څومره زما پوروړی یې، حتی ستا ځان هم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_19.mp3', '', 1761754199, 1761754199),
(31526, 'Philemon 1:20', 'Philemon', 1, 20, 'ای وروره، د څښتن په خاطر ماته ګټه ورسوه او احسان وکړه او په مسیح کې زما زړه قوي او تازه کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_20.mp3', '', 1761754199, 1761754199),
(31527, 'Philemon 1:21', 'Philemon', 1, 21, 'زه ستا په تابعدارۍ باندې باور لرم، نو زه دا شیان تاته لیکم او په دې پوهېږم زه چې درڅخه څه غواړم، د هغې نه به زیات وکړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_21.mp3', '', 1761754199, 1761754199),
(31528, 'Philemon 1:22', 'Philemon', 1, 22, 'بله دا چې زما دپاره یوه کوټه تیاره کړه، ځکه زه هیله لرم چې خدای به ستاسو دعاګانې قبولې کړي او ما به بیا تاسو ته درولي. وروستني سلامونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_22.mp3', '', 1761754199, 1761754199),
(31529, 'Philemon 1:23', 'Philemon', 1, 23, 'اپفراس چې د عیسی مسیح په خاطر زما سره په زندان کې دی، تاته سلام وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_23.mp3', '', 1761754199, 1761754199),
(31530, 'Philemon 1:24', 'Philemon', 1, 24, 'همدارنګه مرقوس، ارسترخوس، دیماس او لوقا چې په دې خدمت کې زما ملګري دي، هم تاته سلام وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_24.mp3', '', 1761754199, 1761754199),
(31531, 'Philemon 1:25', 'Philemon', 1, 25, 'په تاسو ټولو باندې دې زمونږ د څښتن عیسی مسیح فضل وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_25.mp3', '', 1761754199, 1761754199),
(31532, 'Philippians 1:1', 'Philippians', 1, 1, 'دا لیک د پولوس او تیموتاوس له خوا چې د عیسی مسیح خدمتګاران دي، د خدای ټولو خلکو ته چې په فیلیپيې کې اوسیږي او د عیسی مسیح سره تړاو لري او د هغوی مشرانو او خادمانو ته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_1.mp3', '', 1761754199, 1761754199),
(31533, 'Philippians 1:2', 'Philippians', 1, 2, 'زمونږ د پلار خدای او څښتن عیسی مسیح فضل او سلامتي دې وي په تاسو باندې. د لیک د لوستونکو دپاره د پولوس رسول دعا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_2.mp3', '', 1761754199, 1761754199),
(31534, 'Philippians 1:3', 'Philippians', 1, 3, 'زه چې هر وخت تاسو یادوم، نو د خدای شکر وباسم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_3.mp3', '', 1761754199, 1761754199),
(31535, 'Philippians 1:4', 'Philippians', 1, 4, 'کله چې زه تاسو ټول په خپلو دعاګانو کې یادوم، دا زما د خوشحالۍ سبب کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_4.mp3', '', 1761754199, 1761754199),
(31536, 'Philippians 1:5', 'Philippians', 1, 5, 'ځکه چې تاسو د لومړۍ ورځې نه تر‌اوسه پورې زما سره د زېري په خپرولو کې شریک یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_5.mp3', '', 1761754199, 1761754199),
(31537, 'Philippians 1:6', 'Philippians', 1, 6, 'زه په دې ډاډه یم چې خدای چې کوم نېک کار په تاسو کې پیل کړی دی، هغه به د عیسی مسیح د بېرته راتګ تر ورځې پورې پوره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_6.mp3', '', 1761754199, 1761754199),
(31538, 'Philippians 1:7', 'Philippians', 1, 7, 'زه حق لرم چې ستاسو ټولو په هکله داسې احساس ولرم، ځکه چې تاسو زما په زړه کې ځای لرئ. نو که زه په زندان کې یم، یا د زېري نه په دفاع او تصدیق کې بوخت یم، تاسو زما سره د خدای په فضل کې شریک یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_7.mp3', '', 1761754199, 1761754199),
(31539, 'Philippians 1:8', 'Philippians', 1, 8, 'ځکه خدای زما شاهد دی چې زه څومره د عیسی مسیح په مینه کې ستاسو ټولو د لیدلو ارمان لرم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_8.mp3', '', 1761754199, 1761754199),
(31540, 'Philippians 1:9', 'Philippians', 1, 9, 'همدارنګه دا زما دعا ده چې ستاسو مینه دې د علم او پوره پوهې سره نوره هم زیاته شي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_9.mp3', '', 1761754199, 1761754199),
(31541, 'Philippians 1:10', 'Philippians', 1, 10, 'ترڅو تاسو وکولای شئ هرڅه چې ښه دي غوره کړئ او د مسیح د بېرته راتللو تر ورځې پورې پاک او بې‌عیبه پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_10.mp3', '', 1761754199, 1761754199),
(31542, 'Philippians 1:11', 'Philippians', 1, 11, 'ستاسو ژوند دې د عدالت د مېوو نه ډک شي چې د عیسی مسیح په وسیله د خدای د جلال او ستاینې دپاره تر‌لاسه کیږي. مسیح د ژوند مقصد دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_11.mp3', '', 1761754199, 1761754199),
(31543, 'Philippians 1:12', 'Philippians', 1, 12, 'ای خویندو او ورونو! زه غواړم تاسو په دې خبر شئ څه چې زما سره وشول، په حقیقت کې هماغه د زېري د خپرولو سبب شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_12.mp3', '', 1761754199, 1761754199),
(31544, 'Philippians 1:13', 'Philippians', 1, 13, 'نو د امپراتورۍ د ماڼۍ ټول ساتونکي او نور ټول خلک خبر شول چې زه د مسیح په خاطر بندي شوی یم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_13.mp3', '', 1761754199, 1761754199),
(31545, 'Philippians 1:14', 'Philippians', 1, 14, 'او زما بندي کېدل د دې سبب شوی دی چې ډېر زیات ورونه او خویندې په څښتن کې دومره ډاډمن شي چې نور هم د دې زړه پیدا کړي چې د خدای کلام بې له وېرې بیان کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_14.mp3', '', 1761754199, 1761754199),
(31546, 'Philippians 1:15', 'Philippians', 1, 15, 'بې له شکه ځینې د مسیح پیغام د بخیلۍ او سیالۍ له مخې او ځینې یې په ښه نیت سره وعظ کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_15.mp3', '', 1761754199, 1761754199),
(31547, 'Philippians 1:16', 'Philippians', 1, 16, 'هغوی د مینې له مخې داسې کوي، ځکه پوهیږي چې زه د زېري د دفاع په خاطر دلته راوستل شوی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_16.mp3', '', 1761754199, 1761754199),
(31548, 'Philippians 1:17', 'Philippians', 1, 17, 'خو هغه نور د اخلاص له مخې د مسیح په هکله وعظ نه کوي، بلکې د ځان خوښونې له مخې یې کوي او فکر کوي چې په زندان کې به زما تکلیف نور هم زیات کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_17.mp3', '', 1761754199, 1761754199),
(31549, 'Philippians 1:18', 'Philippians', 1, 18, 'څه فرق کوي؟ په هره طریقه چې وي، که هغه د بد نیت له مخې وي یا د ښه نیت، مهمه دا ده چې مسیح خلکو ته اعلان شي. په دې کار زه خوشحاله یم. هو، او خوشحاله به یم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_18.mp3', '', 1761754199, 1761754199),
(31550, 'Philippians 1:19', 'Philippians', 1, 19, 'ځکه زه پوهېږم چې ستاسې دعاګانې او د عیسی مسیح د روح مرسته به زما د خلاصون سبب شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_19.mp3', '', 1761754199, 1761754199),
(31551, 'Philippians 1:20', 'Philippians', 1, 20, 'ځکه دا زما د زړه غوښتنه او زما هیله ده چې زه به هېڅ ونه شرمېږم، بلکې په پوره زړورتیا سره به اوس لکه د تل په شان مسیح ته په خپل بدن کې لویي ورکړم، که دا زما په ژوند وي او یا زما په مرګ باندې تمام شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_20.mp3', '', 1761754199, 1761754199),
(31552, 'Philippians 1:21', 'Philippians', 1, 21, 'ځکه چې د ژوند نه زما مقصد مسیح دی او مرګ هم زما په ګټه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_21.mp3', '', 1761754199, 1761754199),
(31553, 'Philippians 1:22', 'Philippians', 1, 22, 'خو که زه ژوندی پاتې شم، نو وبه کولای شم چې کوم ګټور کار وکړم. خو زه نه پوهېږم چې کوم یو غوره کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_22.mp3', '', 1761754199, 1761754199),
(31554, 'Philippians 1:23', 'Philippians', 1, 23, 'زه په دواړو کې حیران پاتې یم. زه غواړم چې د دې دنیا نه لاړ شم او د مسیح سره واوسم، ځکه چې دا به ډېر ښه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_23.mp3', '', 1761754199, 1761754199),
(31555, 'Philippians 1:24', 'Philippians', 1, 24, 'خو زما ژوندي پاتې کېدل ستاسو دپاره ډېر ضروري دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_24.mp3', '', 1761754199, 1761754199),
(31556, 'Philippians 1:25', 'Philippians', 1, 25, 'زه په دې ډاډه یم او په دې پوهېږم چې ژوندی به پاتې شم او تاسو ټولو سره به یم چې تاسو په ایمان کې پرمختګ او خوشحالي وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_25.mp3', '', 1761754199, 1761754199),
(31557, 'Philippians 1:26', 'Philippians', 1, 26, 'کله چې زه بېرته تاسو ته درشم، نو ستاسو سره به ښه دلیل وي چې زما له امله په عیسی مسیح کې ډېر زیات ویاړ وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_26.mp3', '', 1761754199, 1761754199),
(31558, 'Philippians 1:27', 'Philippians', 1, 27, 'په هر حال، داسې ژوند کوئ چې ستاسو چلند د مسیح د زېري له مخې وي، نو که زه راشم او تاسو ووینم او یا رانه شم، زه غواړم ستاسو په هکله واورم چې په یو روح او یو مقصد کې ټینګ ولاړ یئ او یو د بل سره څنګ تر‌څنګ په زېري باندې د ایمان دپاره هلې ځلې کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_27.mp3', '', 1761754199, 1761754199),
(31559, 'Philippians 1:28', 'Philippians', 1, 28, 'په هېڅ ډول د خپلو مخالفینو نه مه وېرېږئ، دا به ثابته شي چې هغوی د تباهۍ خواته روان دي او تاسو به خلاصون ومومئ او دا هرڅه د خدای له خوا دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_28.mp3', '', 1761754199, 1761754199),
(31560, 'Philippians 1:29', 'Philippians', 1, 29, 'ځکه چې دا امتیاز تاسو ته درکړل شوی دی چې نه یوازې دا چې په عیسی مسیح باندې ایمان راوړئ، بلکې د هغه په خاطر کړاوونه وزغمئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_29.mp3', '', 1761754199, 1761754199),
(31561, 'Philippians 1:30', 'Philippians', 1, 30, 'تاسو هم په هغې مبارزه کې بوخت یئ چې زه په کې بوخت وم او تاسو خپله ولیدل او خبر یئ چې زه لا تر‌اوسه هم په کې بوخت یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians1_verse_30.mp3', '', 1761754199, 1761754199),
(31562, 'Revelation 2:1', 'Revelation', 2, 1, 'د افسیس د کلیسا فرښتې ته ولیکه: «دا د هغه چا خبرې دي چې اووه ستوري یې په خپل ښي لاس کې نیولي دي او د سرو زرو د اوو څراغدانونو په منځ کې ګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation2_verse_1.mp3', '', 1761754199, 1761754199),
(31563, 'Revelation 2:2', 'Revelation', 2, 2, 'ستاسو کلیسا چې کوم زحمتونه ویستلي دي زه د هغو ټولو نه خبر یم. ما ستاسو زیار، صبر او زغم لیدلی دی. زه پوهېږم چې تاسو بدکاره خلک زغملی نه شئ. تاسو هغه خلک ازمایلي دي چې ځان ته رسولان وایي خو نه دي او پوه شوي یئ چې هغوی دروغجن دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation2_verse_2.mp3', '', 1761754199, 1761754199),
(31564, 'Revelation 2:3', 'Revelation', 2, 3, 'زه پوهېږم چې تاسو صبر او زغم لرئ، تاسو زما په خاطر ډېرې ستونزې زغملې دي او ستومانه شوي نه یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation2_verse_3.mp3', '', 1761754199, 1761754199),
(31565, 'Revelation 2:4', 'Revelation', 2, 4, 'خو زه ستاسو نه یوه ګیله لرم چې تاسو خپله لومړنۍ مینه له لاسه ورکړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation2_verse_4.mp3', '', 1761754199, 1761754199),
(31566, 'Revelation 2:5', 'Revelation', 2, 5, 'خو په یاد ولرئ چې تاسو د څومره لوړ مقام نه رالوېدلي یئ، نو توبه وباسئ او هغه کارونه کوئ چې مخکې مو کول. که توبه ونه باسئ، نو زه به درشم او ستاسو څراغدان به د خپل ځای نه لېرې کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation2_verse_5.mp3', '', 1761754199, 1761754199),
(31567, 'Revelation 2:6', 'Revelation', 2, 6, 'خو په تاسو کې یو ښه‌والی شته چې تاسو د نیکولاویانو د کارونو څخه کرکه کوئ، لکه څنګه چې زه ورڅخه کرکه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation2_verse_6.mp3', '', 1761754199, 1761754199),
