(31598, 'Luke 22:8', 'Luke', 22, 8, 'نو عیسی پطروس او یوحنا ولېږل او ورته ویې ویل: «لاړ شئ او زمونږ دپاره د فسحې ډوډۍ تیاره کړئ چې ویې خورو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_8.mp3', '', 1761754199, 1761754199),
(31599, 'Luke 22:9', 'Luke', 22, 9, 'هغوی ورڅخه پوښتنه وکړه: «په کوم ځای کې غواړې چې تیاره یې کړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_9.mp3', '', 1761754199, 1761754199),
(31600, 'Luke 22:10', 'Luke', 22, 10, 'هغه ځواب ورکړ: «ګورئ، څنګه چې ښار ته ننوځئ، نو یو سړی به ستاسو سره مخامخ شي چې د اوبو منګی به و‌ړي. هغه چې کوم کور ته ننوځي، تاسو هم ورپسې لاړ شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_10.mp3', '', 1761754199, 1761754199),
(31601, 'Luke 22:11', 'Luke', 22, 11, 'او د کور خاوند ته ووایئ: ‹استاذ وایي د مېلمنو کوټه چېرته ده چې زه په کې د خپلو شاګردانو سره د فسحې ډوډۍ وخورم؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_11.mp3', '', 1761754199, 1761754199),
(31602, 'Luke 22:12', 'Luke', 22, 12, 'هغه به تاسو ته پاس په بالاخانه کې یوه لویه فرش شوې کوټه دروښایي، نو هلته ډوډۍ تیاره کړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_12.mp3', '', 1761754199, 1761754199),
(31603, 'Luke 22:13', 'Luke', 22, 13, 'هغوی لاړل او ټول شیان یې لکه څنګه چې عیسی ورته ویلي وو په هماغه ډول ولیدل او د فسحې ډوډۍ یې تیاره کړه. د څښتن غوره ماښامی (متي ۲۶‏:‌۲۶‌‏-‌۳۰ او مرقوس ۱۴‏:‌۲۲‌‏-‌۲۶ او لومړی قرنتیان ۱۱‏:‌۲۳‌‏-‌۲۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_13.mp3', '', 1761754199, 1761754199),
(31604, 'Luke 22:14', 'Luke', 22, 14, 'کله چې هغه ساعت راورسېد، عیسی د خپلو رسولانو سره دسترخوان ته کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_14.mp3', '', 1761754199, 1761754199),
(31605, 'Luke 22:15', 'Luke', 22, 15, 'هغوی ته یې وویل: «زړه مې ډېر غوښتل چې د کړاوونو د زغملو څخه مخکې ستاسو سره د فسحې ډوډۍ وخورم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_15.mp3', '', 1761754199, 1761754199),
(31606, 'Luke 22:16', 'Luke', 22, 16, 'ځکه زه تاسو ته وایم چې ترڅو پورې د فسحې د قربانۍ مقصد د خدای په پاچاهۍ کې پوره نه شي، تر هغې پورې به نور دا ډوډۍ ونه خورم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_16.mp3', '', 1761754199, 1761754199),
(31607, 'Luke 22:17', 'Luke', 22, 17, 'بیا عیسی پیاله راواخیستله، شکر یې وویست او ویې ویل: «دا واخلئ او په خپل منځ کې یې ووېشئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_17.mp3', '', 1761754199, 1761754199),
(31608, 'Luke 22:18', 'Luke', 22, 18, 'ځکه زه تاسو ته وایم چې له دې وروسته به تر هغې پورې د انګورو شربت ونه څښم، ترڅو د خدای پاچاهي رانه شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_18.mp3', '', 1761754199, 1761754199),
(31609, 'Luke 22:19', 'Luke', 22, 19, 'بیا هغه یوه ډوډۍ راواخیستله، شکر یې پرې وویست، هغه یې ماته کړه او هغوی ته یې ورکړه او ویې ویل: «دا زما بدن دی چې ستاسو دپاره ورکول کیږي. زما په یاد همداسې کوئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_19.mp3', '', 1761754199, 1761754199),
(31610, 'Luke 22:20', 'Luke', 22, 20, 'په همدې ډول د ماښام ډوډۍ څخه وروسته یې پیاله راواخیستله او ویې ویل: «دا پیاله د خدای او انسانانو ترمنځ نوی لوظ دی چې زما د وینې په وسیله جوړیږي چې ستاسو دپاره توییږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_20.mp3', '', 1761754199, 1761754199);